import jwt from 'jsonwebtoken';

export function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, message: 'Authorization token required.' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ success: false, message: 'Session expired. Please log in again.' });
  }
}`},{id:"step_6",stepNumber:6,name:"createItem()",type:"controller",category:"Controller Logic",filePath:"backend/controllers/itemController.js",line:28,params:["req: AuthenticatedRequest","res: Response"],calls:["validateItemData()","Item.create()"],calledBy:["itemRoutes.js:21 after authenticate()"],apiEndpoint:"POST /api/items",dbOperation:"Delegates to Mongoose Item model",branchConditions:["if (!validation.isValid) -> res.status(400).json({ errors })","if (database error) -> res.status(500).json({ error })"],errorHandling:"Encapsulated in try/catch block; logs stack trace and returns sanitized client error.",summary:"Extracts request body, coordinates business validation, constructs model instance, and dispatches to database.",codeSnippet:`// backend/controllers/itemController.js:28
import Item from '../models/Item.js';
import { validateItemData } from './validation.js';

export async function createItem(req, res) {
  try {
    const { title, description, category, location, dateLost, imageUrl } = req.body;

    const validation = validateItemData({ title, category, location });
    if (!validation.isValid) {
      return res.status(400).json({ success: false, errors: validation.errors });
    }

    const newItem = await Item.create({
      reporter: req.user.id,
      title: title.trim(),
      description: description || '',
      category,
      location,
      dateLost: dateLost || new Date(),
      status: 'reported',
      imageUrl: imageUrl || null
    });

    return res.status(201).json({
      success: true,
      message: 'Item registered successfully.',
      item: newItem
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
}`},{id:"step_7",stepNumber:7,name:"Validate item data (Mongoose Schema)",type:"model_validation",category:"Model & Schema Guard",filePath:"backend/models/Item.js",line:32,params:["schemaDoc: ItemDocument"],calls:["mongoose.Schema.validate()"],calledBy:["Item.create() in itemController.js:40"],apiEndpoint:"N/A",dbOperation:"Pre-save schema validation hook",branchConditions:["title: required, minlength: 3, maxlength: 120",'category: enum ["electronics", "documents", "clothing", "keys", "other"]',"location: required, trim"],errorHandling:"Mongoose ValidationError thrown if any field fails schema constraints.",summary:'Mongoose compiles schema validators, applies default fields (status="reported"), and runs pre-save hooks.',codeSnippet:`// backend/models/Item.js:32
